"""Blind first; locally gated technical reveal. No cache assets are published."""
from pathlib import Path
import json,shutil,html,hashlib
T=Path(__file__).resolve().parent;E=T.parents[3];R=E/'concept-ab-private';P=T.parents[2]/'art/tower/concept-ab'
mapping=json.loads((R/'blind-mapping.json').read_text());geometry=json.loads((R/'geometry-comparison.json').read_text());effort=json.loads((R/'effort.json').read_text());findings=json.loads((R/'findings.json').read_text())
CSS='''*{box-sizing:border-box}body{margin:0;background:#10171b;color:#e4e9e7;font:16px/1.6 system-ui,sans-serif}main{max-width:1450px;margin:auto;padding:42px 30px 90px}h1{font:500 clamp(35px,4vw,65px)/1.1 Georgia,serif;margin:15px 0 20px;letter-spacing:-1px}h2{font:500 29px/1.2 Georgia,serif;margin:40px 0 16px}h3{font-size:18px}.eyebrow{color:#cfae7f;font-size:12px;letter-spacing:2px;text-transform:uppercase}.intro{max-width:850px;color:#b5c3c5}a{color:#d9bb8e}button,select,input,textarea{font:inherit;border:1px solid #425257;background:#1e2b31;color:#edf0eb;border-radius:5px;padding:9px 14px}button{cursor:pointer}button:hover,button.active{background:#80613f;border-color:#c9a978}button:disabled{opacity:.45;cursor:default}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:23px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#142026;border:1px solid #2b3a40;border-radius:8px;overflow:hidden}.label{padding:12px 18px;display:flex;justify-content:space-between;font-weight:600}.card img{display:block;width:100%;height:auto;background:#0f161c}.caption,small{font-size:13px;color:#a9b9bd}.caption{padding:10px 18px}.notice{padding:14px 18px;border-left:3px solid #c8a371;background:#1b252a;margin:25px 0}.score{display:grid;grid-template-columns:2fr 1fr;gap:12px;align-items:center;max-width:800px;margin:12px 0}textarea{width:100%;min-height:90px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:12px;border-bottom:1px solid #3a484c;vertical-align:top}th{color:#d2b88e}.refs{display:grid;grid-template-columns:1fr 1fr;gap:16px}.refs img{width:100%;height:auto}code{font-size:13px;color:#d6c2a4}details{margin:18px 0;padding:12px 18px;background:#1a282e}.gate{padding:25px;border:1px solid #77664d;margin-top:38px}li{margin:9px 0}pre{white-space:pre-wrap;background:#172328;padding:18px;overflow-wrap:anywhere}.hidden{display:none}@media(max-width:800px){main{padding:25px 14px}.pair,.refs{grid-template-columns:1fr}.score{grid-template-columns:1fr}}'''
def esc(s):return html.escape(str(s))
def shell(title,content,script=''):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><style>'+CSS+'</style><main>'+content+'</main><script>'+script+'</script></html>'
for label,method in mapping.items():
    dest=R/'blind'/label;dest.mkdir(parents=True,exist_ok=True)
    for mode in ['quarter','gameplay']:shutil.copy2(R/'environment'/f'{method}-{mode}-final/scene.png',dest/('environment-'+mode+'.png'))
def blind(private):
    prefix='../concept-ab-server/art/tower/concept-ab/' if private else ''
    views={'quarter':'Three-quarter','front':'Front','side':'Side','rear':'Rear','above':'Elevated','gameplay':'Gameplay scale','face':'Face detail','armor':'Armor detail'}
    if private:views.update({'environment-quarter':'Authentic environment','environment-gameplay':'Environment gameplay'})
    body='<div class="eyebrow">ASCENT · One frozen creature · Two independent models</div><h1>Ashhorn Stalker.<br>Compare the meshes.</h1><p class="intro">Evaluate the native-rendered creature before seeing how it was made. Both models use one frozen design, the same native conversion, palette, scale, cameras and lighting. Labels are randomized and creation methods are concealed here.</p><div class="notice">Static experiment only. No live map, cache, NPC definition, renderer or gameplay changes. Neither model is artistically approved. Concept imagery was displayed during generation, so this is an attribution-blind review rather than a fully blinded experiment.</div>'
    body+='<div class="toolbar" id="views">'+''.join('<button data-view="'+k+'">'+v+'</button>' for k,v in views.items())+'</div><div class="toolbar"><button id="native" class="active">Native Rust</button><button id="studio">Blender studio supplement</button></div><p class="caption" id="condition"></p><div class="pair">'
    for label in ['A','B']:body+='<article class="card"><div class="label"><span>Model '+label+'</span><span class="angle"></span></div><a class="full" target="_blank"><img id="image'+label+'" alt="Model '+label+' matched render"></a><div class="caption">Click to inspect the untouched full-resolution render.</div></article>'
    body+='</div><h2>Record your first impression.</h2><p class="intro">Judge anatomy, facial identity, armor and surface construction separately. A tie or neither is a useful result. These selections stay in this browser unless you download and share them.</p>'
    for key,title in [('anatomy','More convincing anatomy'),('face','Stronger face and identity'),('surfaces','More coherent armor and surfaces'),('compatibility','Better fit in the authentic environment'),('overall','Overall visual preference')]:
        body+='<label class="score">'+title+'<select id="'+key+'"><option value="">Choose…</option><option>A</option><option>B</option><option>Tie</option><option>Neither</option></select></label>'
    body+='<textarea id="notes" aria-label="Review notes" placeholder="What looks convincing, and what still needs work?"></textarea><div class="toolbar"><button id="download">Download assessment</button></div><div class="gate"><label><input type="checkbox" id="reviewed"> I have finished my visual assessment.</label><p class="caption">The next stage reveals the methods, concept sheets, iteration history, measured effort, engineering checks and limitations.</p><button id="reveal" disabled>Reveal methods and technical comparison</button></div><p class="caption">Shared specification SHA-256: <code>ce0cb460a95c8b5a62c1a561f40bf21e4571befd9b1cd55ef2b03dc3937518f8</code>. Preview images fit the columns; gameplay files retain their native765×503 frames. Studio images use equivalent cameras with supplementary Cycles lighting.</p>'
    data={'prefix':prefix,'private':private,'views':views}
    js='const DATA='+json.dumps(data)+';'+'''
let view='quarter',mode='native';const keys=['anatomy','face','surfaces','compatibility','overall'];
function update(){const env=view.startsWith('environment-');const detail=['face','armor'].includes(view);if(env||detail)mode='native';
 for(const label of ['A','B']){const path=env?'blind/'+label+'/'+view+'.png':DATA.prefix+'models/'+label+'/'+mode+'/'+view+'.png';const im=document.getElementById('image'+label);im.src=path;im.parentElement.href=path;}
 document.querySelectorAll('.angle').forEach(n=>n.textContent=DATA.views[view]);document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===view));
 document.getElementById('native').classList.toggle('active',mode==='native');document.getElementById('studio').classList.toggle('active',mode==='studio');document.getElementById('studio').disabled=env||detail;
 document.getElementById('condition').textContent=env?'Same real revision239.1 courtyard terrain and scenery, actor origin and ground height; read-only offline submission.':mode==='studio'?'Supplementary Cycles32-sample/AgX lighting, with fixed canonical bounds and equivalent native camera; not native acceptance evidence.':'Unchanged native Rust renderer · ambient72 · contrast850 · light[-30,-50,-30] · palette brightness0.8 · no candidate alignment or individual rescaling.';
}
document.querySelectorAll('[data-view]').forEach(n=>n.onclick=()=>{view=n.dataset.view;update();});for(const m of ['native','studio'])document.getElementById(m).onclick=()=>{mode=m;update();};
function feedback(){return {schema:1,reviewed_at:new Date().toISOString(),ratings:Object.fromEntries(keys.map(k=>[k,document.getElementById(k).value])),notes:document.getElementById('notes').value,artistic_approval:false};}
function save(){try{localStorage.setItem('ashhorn-blind-review',JSON.stringify(feedback()));}catch(e){}}
document.getElementById('download').onclick=()=>{save();let u=URL.createObjectURL(new Blob([JSON.stringify(feedback(),null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='ashhorn-blind-assessment.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
document.getElementById('reviewed').onchange=e=>document.getElementById('reveal').disabled=!e.target.checked;
document.getElementById('reveal').onclick=()=>{save();location.href='technical/index.html';};update();
'''
    return shell('Ashhorn Stalker — Blind A/B Review',body,js),js
def technical(private):
    prefix='../../concept-ab-server/art/tower/concept-ab/' if private else '../'
    body='<div class="eyebrow">ASCENT · Stage2 · Technical reveal</div><h1>What the images changed.<br>What they did not.</h1><p><a href="../index.html">Return to the blind comparison</a></p><div class="notice">This stage discloses the workflow identities. User artistic preference and approval remain pending; this is one unequal-effort pilot, not a causal proof.</div><table><tr><th>Blind label</th><th>Workflow</th><th>Final mesh</th><th>Authoring evidence</th></tr>'
    for label,method in mapping.items():
        m=geometry[label];e=effort['methods'][method]
        body+='<tr><td>'+label+'</td><td>'+('Frozen text only; completed before AI generation' if method=='text' else 'AI concept/turnaround guidance; independent empty-scene construction')+'</td><td>'+str(m['triangles'])+' triangles; '+str(m['vertices'])+' vertices<br>'+str(m['dimensions_x_y_z_authoring'])+' native units</td><td>'+str(e['modeling_iterations'])+' successful modeling passes; '+str(e['failed_blender_attempts'])+' failed<br>'+str(round(e['authoring_envelope_seconds']))+'s measured authoring envelope</td></tr>'
    body+='</table><h2>Finding</h2><p>'+esc(findings['method_selection'])+'</p>'
    for title,value in findings['assessments'].items():body+='<h3>'+esc(title.replace('_',' ').capitalize())+'</h3><p>'+esc(value)+'</p>'
    body+='<h2>Original concept and turnaround</h2><p>Built-in image_gen, three calls, approximately85.9s tool execution. No protected cache assets were supplied. The raw hero, first sheet and toe-corrected sheet are preserved; the final sheet is accepted only as a modeling guide.</p><div class="refs"><a href="'+prefix+'technical/original-concept/hero.png"><img src="'+prefix+'technical/original-concept/hero.png" alt="Original generated concept"></a><a href="'+prefix+'technical/original-concept/turnaround-v2.png"><img src="'+prefix+'technical/original-concept/turnaround-v2.png" alt="Corrected turnaround"></a></div><p><a href="'+prefix+'technical/original-concept/consistency.json">Consistency, calibration, landmarks and unresolved conflicts</a> · <a href="'+prefix+'technical/original-concept/turnaround-v1.png">Preserved first turnaround</a> · <a href="'+prefix+'technical/original-concept/hero-tool-prompt.txt">Exact hero generation prompt</a> · <a href="'+prefix+'technical/original-concept/turnaround-prompt.txt">Turnaround prompt</a> · <a href="'+prefix+'technical/original-concept/toe-correction-prompt.txt">Toe correction prompt</a></p>'
    body+='<h2>From blockout to selected mesh</h2><p>These preserved history images use the same original fixed three-quarter camera. Full editable checkpoints and source recipes are linked below.</p>'
    for label in ['A','B']:
        body+='<h3>Model '+label+'</h3><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">'
        for phase in ['blockout','refined','final']:body+='<article class="card"><div class="label">'+phase+'</div><a href="'+prefix+'history/'+label+'/'+phase+'/source.blend"><img src="'+prefix+'history/'+label+'/'+phase+'/quarter.png" alt="'+label+' '+phase+'"></a></article>'
        body+='</div><p><a href="'+prefix+'models/'+label+'/source.blend">Final editable Blender source</a> · <a href="'+prefix+'models/'+label+'/asset.model">Native model</a> · <a href="'+prefix+'models/'+label+'/recipe.json">Recipe</a> · <a href="'+prefix+'models/'+label+'/conversion.json">Conversion accounting</a></p>'
    body+='<h2>Measured effort and major corrections</h2><p>'+esc(effort['time_basis'])+'</p>'
    for label,method in mapping.items():
        e=effort['methods'][method];body+='<details><summary>Model '+label+' · '+str(e['modeling_iterations'])+' successful passes / '+str(e['native_modeling_views'])+' native modeling views</summary><ol>'
        for x in e['candidates']:body+='<li><b>'+esc(x['name'])+'</b> — '+esc(x['reason'])+'</li>'
        body+='</ol><p>Blender execution '+str(round(e['blender_execution_seconds'],2))+'s; native model rendering '+str(round(e['native_execution_seconds'],2))+'s. Time envelope '+esc(e['authoring_envelope_utc'])+'.</p></details>'
    body+='<p>The concept preparation envelope is '+str(round(effort['concept_preparation']['elapsed_preparation_seconds']))+'s. Its extra modeling iteration and shell-cage scripting confound a claim that image guidance alone caused any improvement.</p><h2>Engineering and source safeguards</h2><p>Both saved sources re-export byte-exactly; fresh recipes reproduce both payloads and all six original native views pixel-for-pixel. Native decoding preserves vertices, faces, colors and render flags. Each mesh has12 named toes/claws and five dorsal shields. No selected native triangles are degenerate. Native quantization drops179 and201 source triangles respectively; those losses and open/detail boundaries remain reported.</p><p>Shared authoring tools are unchanged from <code>8b85f19ce2d70988b0724f1d03e241c29a45daf6</code>. Blender5.2.2LTS, build<code>d13f752e3b9c</code>. Frozen native executable SHA-256:<code>f6e6e12da1a80f7824c9d90a5254964fdc8d738298417c7dcd51e0793caea7cf</code>. The new read-only environment adapter calls unchanged native client rendering APIs. Static registry IDs are experimental proxies, not installed NPC definitions.</p><p><a href="'+prefix+'registry.json">Isolated registry and original ID bounds</a> · <a href="'+prefix+'design.json">Frozen original specification</a> · <a href="'+prefix+'technical/effort.json">Measured effort</a> · <a href="'+prefix+'technical/findings.json">Findings</a> · <a href="'+prefix+'technical/geometry-comparison.json">Geometry comparison</a> · <a href="'+prefix+'manifest.json">Original artifact hashes</a></p>'
    if private:body+='<p><a href="../verification.json">Private full verification</a> · <a href="../reproduction.json">Fresh reproduction</a> · <a href="../preservation.json">Preservation and tool identities</a> · <a href="../publication.json">Final source publication identity</a></p>'
    body+='<h2>Limits of this pilot</h2><ul>'+''.join('<li>'+esc(x)+'</li>'for x in findings['limitations'])+'</ul><h2>Reusable findings</h2><ul>'+''.join('<li>'+esc(x)+'</li>'for x in findings['reusable_findings'])+'</ul><p>Protected original cache data, extracted reference models, runtime palettes and authentic environment screenshots stay in the local private review directory. Public artifacts contain only the original creature models, original generated artwork, standalone original renders and source-safe findings.</p>'
    return shell('Ashhorn Stalker — Technical Comparison',body)
for private,root in [(True,R),(False,P)]:
    page,js=blind(private);(root/'index.html').write_text(page,encoding='utf8');(root/'gallery.js').write_text(js,encoding='utf8');(root/'technical').mkdir(exist_ok=True);(root/'technical/index.html').write_text(technical(private),encoding='utf8')
for name in ['effort.json','findings.json','geometry-comparison.json']:shutil.copy2(R/name,P/'technical'/name)
print('Private cache-backed and public original-only blind galleries built; technical reveal is gated.')
